class Solution { public: double largestTriangleArea(vector<vector<int>>& points){long long twice=0;for(int i=0;i<(int)points.size();++i)for(int j=i+1;j<(int)points.size();++j)for(int k=j+1;k<(int)points.size();++k){long long cross=(long long)(points[j][0]-points[i][0])*(points[k][1]-points[i][1])-(long long)(points[j][1]-points[i][1])*(points[k][0]-points[i][0]);twice=max(twice,llabs(cross));}return twice/2.0;} };
